	/*
     * @param	event CreateDataProviderEvent
     */
    @EventHandler( payloadType=CreateDataProviderEvent.class )
    public void handle( CreateDataProviderEvent event) {
	    LOGGER.info("handling CreateDataProviderEvent - " + event );
	    DataProvider entity = new DataProvider();
            entity.setDataProviderId( event.getDataProviderId() );
            entity.setName( event.getName() );
            entity.setWebsite( event.getWebsite() );
            entity.setProviderType( event.getProviderType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllDataProvider( entity );
    }

    /*
     * @param	event UpdateDataProviderEvent
     */
    @EventHandler( payloadType=UpdateDataProviderEvent.class )
    public void handle( UpdateDataProviderEvent event) {
    	LOGGER.info("handling UpdateDataProviderEvent - " + event );
    	
	    DataProvider entity = new DataProvider();
            entity.setDataProviderId( event.getDataProviderId() );
            entity.setName( event.getName() );
            entity.setWebsite( event.getWebsite() );
            entity.setAudienceSegments( event.getAudienceSegments() );
            entity.setProviderType( event.getProviderType() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindDataProvider( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllDataProvider( entity );        
    }
    
