/**
 * emit to subscription queries of type FindDataProvider,
 * but only if the id matches
 *
 * @param		entity	DataProvider
 */
	protected void emitFindDataProvider( DataProvider entity ) {
		LOGGER.info("handling emitFindDataProvider" );
		
	    queryUpdateEmitter.emit(FindDataProviderQuery.class,
	                            query -> query.getFilter().getDataProviderId().equals(entity.getDataProviderId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllDataProvider
	 * 
	 * @param		entity	DataProvider
	 */
	protected void emitFindAllDataProvider( DataProvider entity ) {
		LOGGER.info("handling emitFindAllDataProvider" );
		
	    queryUpdateEmitter.emit(FindAllDataProviderQuery.class,
	                            query -> true,
	                            entity);
	}

